protected void updateParentMovement(
    InventMovement      _parentMovement,
    InventQty           _qtyAdjusted,
    Qty                 _qtyAdjustedUnit,
    PdsCWInventQty      _pdsCWQtyAdjusted)
{
    if (PdsGlobal::pdsIsCWItem(_parentMovement.itemId()) 
        && wmsOrderTrans.Orig().PdsCWQty == wmsOrderTrans.PdsCWQty 
        && !_pdsCWQtyAdjusted)
    {
        _qtyAdjustedUnit = 0;
    }

    next updateParentMovement(_parentMovement, _qtyAdjusted, _qtyAdjustedUnit, _pdsCWQtyAdjusted);
}
